<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id'])){http_response_code(403);exit('Nicht angemeldet.');}require_once dirname(__DIR__).'/private/finance_service.php';require_once dirname(__DIR__).'/private/invoice_lib.php';
$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');if(!zgsValidDate($from)||!zgsValidDate($to)||$from>$to){http_response_code(400);exit('Zeitraum ungültig.');}
$q=$pdo->prepare('SELECT p.id,p.paid_on,p.amount_cents,p.tax_cents,p.invoice_id,i.number invoice_number,p.receipt_id,r.number receipt_number,r.document_id,d.sha256,p.bank_transaction_id,p.reversal_of,p.reason FROM finance_payments p LEFT JOIN invoices i ON i.id=p.invoice_id LEFT JOIN finance_receipts r ON r.id=p.receipt_id LEFT JOIN documents d ON d.id=r.document_id WHERE p.paid_on BETWEEN ? AND ? ORDER BY p.paid_on,p.id');$q->execute([$from,$to]);
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="gsz-pruefliste.csv"');echo "\xEF\xBB\xBF";echo implode(';',array_map('invCsvCell',['Zahlung','Datum','Betrag EUR','USt-Anteil EUR','Rechnung-ID','Rechnungsnummer','Beleg-ID','Belegnummer','Original-Dokument-ID','Original-SHA256','Bankumsatz-ID','Gegenzeile-zu','Korrekturgrund']))."\r\n";while($r=$q->fetch()){$r['amount_cents']=financeDecimal((int)$r['amount_cents']);$r['tax_cents']=financeDecimal((int)$r['tax_cents']);echo implode(';',array_map('invCsvCell',array_values($r)))."\r\n";}
